arguments.command:
cd /tmp/vally-eval-trial-FU4ZYa && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount && 
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4).
  # NOT DECIDED: Platinum. The business has not agreed a reduction, so no scenario
  # exists for it and none may be invented. See "Open decisions" in test-plan-discount.md.

  @happy-path @smoke
  Scenario Outline: Returning customer is charged the amount for their loyalty tier
    Given a returning customer in the <tier> tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged <charged> cents

    Examples: AC-1, AC-2, AC-3
      | tier   | charged |
      | Bronze | 9500    |
      | Silver | 9000    |
      | Gold   | 8500    |

  @edge-case
  Scenario: Returning customer's reduction lands on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Returning customer is charged the amount for their loyalty tier (AC-1, AC-2, AC-3)
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    [InlineData(LoyaltyTier.Silver, 10000, 9000)]
    [InlineData(LoyaltyTier.Gold, 10000, 8500)]
    public void Returning_customer_is_charged_the_amount_for_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
EOF
D=$P/evidence/2026-10-09/discount && mkdir -p $D
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $D/acceptance-red.stdout 2>&1; echo $? > $D/acceptance-red.exit; git rev-parse HEAD > $D/acceptance-red.rev
cat $D/acceptance-red.exit; grep -E "Assert|Expected|Actual|Failed|error" $D/acceptance-red.stdout | head -20

